"""Arm `pbj`: the incumbent's dispatcher. Emitted beside `Arms` so the payload switch is
written once per arm rather than once per payload per arm."""
import java_names as N

HEAD = ("// @generated by ffi/poc/java/gen/generate.py from ffi/schema/shapes.json."
        " Do not edit.\n")


def emit(ir, ns=N.PKG):
    o = [HEAD, "package %s;" % ns, "",
         "import com.google.protobuf.CodedOutputStream;",
         "import com.google.protobuf.Message;", "",
         "/** Arm `pbj`: protobuf-java, the baseline every ratio is against.",
         " *",
         " *  <p>Three encode entry points, not one, because the cpp slice's review found",
         " *  its own incumbent handicapped three ways and it was worth about 8 points of",
         " *  every encode ratio (findings/cpp.md section 1). So this arm measures what",
         " *  the LIBRARY does rather than what a harness author writes:",
         " *  <ul>",
         " *    <li>{@code toByteArray()} -- the idiomatic entry point, which sizes once",
         " *        and allocates an exactly-sized array per call;</li>",
         " *    <li>{@code writeTo(CodedOutputStream)} over a REUSED array, which is what",
         " *        the core arms get and therefore the only fair encode comparison for",
         " *        them;</li>",
         " *    <li>the same, with deterministic serialization, which is what sorts map",
         " *        entries. The canonical form of schema/README sorts them, so byte",
         " *        identity needs this; it is priced separately rather than charged to",
         " *        the headline, which is the other half of the cpp slice's C7.</li>",
         " *  </ul>",
         " */",
         "public final class PbArms {",
         "  private PbArms() {}", ""]
    rows = []
    for pid, spec in ir.payloads.items():
        if spec["root"] not in ir.messages:
            continue
        rows.append((pid, spec))

    o.append("  public static Message build(String id, int cs) {")
    o.append("    switch (id) {")
    for pid, spec in rows:
        if spec.get("interleaved"):
            o.append('      case "%s": return null;   // decode only' % pid)
        else:
            o.append('      case "%s": return PbBuild.payload%s(cs);'
                     % (pid, pid.replace(".", "_")))
    o.append('      default: throw new IllegalArgumentException(id);')
    o.append("    }")
    o.append("  }")
    o.append("")
    o.append("  public static Message parse(String id, byte[] b, int off, int len)")
    o.append("      throws com.google.protobuf.InvalidProtocolBufferException {")
    o.append("    switch (id) {")
    for pid, spec in rows:
        o.append('      case "%s": return ak.pb.%s.parseFrom('
                 'java.nio.ByteBuffer.wrap(b, off, len));' % (pid, spec["root"]))
    o.append('      default: throw new IllegalArgumentException(id);')
    o.append("    }")
    o.append("  }")
    o.append("}")
    o.append("")
    return "\n".join(o)
